// LEA-160: sentences that are played when OpenAI cannot speak (the connection has just dropped). They are recorded in
// advance as the phone line's own format (μ-law 8 kHz, base64), so they need no connection to anyone. Generated by
// `npm run fallback-audio` (src/scripts/make-fallback-audio.ts); the texts are in that script.
import { FALLBACK_CLIPS } from "./fallback-audio-data";

export type ClipKind = "wait" | "apology";

/** The recorded sentence for this language, or null when there is none (a browser test call has no phone format). */
export function fallbackClip(kind: ClipKind, language: "cs" | "en"): string | null {
  const clip = FALLBACK_CLIPS[language]?.[kind] ?? "";
  return clip ? clip : null;
}
